import { getConf } from '@jbrowse/core/configuration'
import {
  fetchAlphaFoldModels,
  getAlphaFoldStructureUrl,
  pickAlphaFoldModel,
  searchUniProtEntries,
} from 'p2s_mapper'

import { codingTranscripts, flaggedTranscriptId } from './codingFeature'
import {
  rankIsoforms,
  rankedTranscriptId,
} from '../AlignTranscriptRpc/isoformRanking'
import { fetchTranscriptProteinSeqs } from './utils/translateTranscripts'
import { extractFeatureIdentifiers, extractTaxonId } from './utils/util'
import { alignOffThread } from '../ProteinView/alignOffThread'

import type { IsoformRanking } from '../AlignTranscriptRpc/isoformRanking'
import type { TranscriptTranslation } from './utils/translateTranscripts'
import type { FeatureIdentifiers } from './utils/util'
import type { AbstractSessionModel, Feature } from '@jbrowse/core/util'
import type { AlphaFoldModel, Isoform, UniProtEntry } from 'p2s_mapper'

export interface GeneLaunch {
  transcript: Feature
  userProvidedTranscriptSequence: string
  /** undefined when the gene's identifiers name no single UniProt entry */
  uniprotId?: string
  /** why the UniProt search gave no answer, as opposed to answering "none" */
  lookupError?: unknown
  /** the AlphaFold model of that entry; undefined when it has none */
  url?: string
}

interface EntryLookup {
  uniprotId?: string
  lookupError?: unknown
}

export type LaunchAlphaFoldModel = Pick<AlphaFoldModel, 'accession' | 'url'> &
  Partial<Pick<AlphaFoldModel, 'sequence' | 'confidenceUrl'>>

/**
 * The AlphaFold file a launch opens, `models` undefined when the API did not
 * answer. That says nothing about the accession, so the spelled canonical
 * filename is worth a try; an API answering with no models has said there is
 * nothing to open. The structure loader draws the same line.
 */
export function launchAlphaFoldModel(
  uniprotId: string,
  models: AlphaFoldModel[] | undefined,
  isoformSequences: Record<string, { seq: string }> | undefined,
): LaunchAlphaFoldModel | undefined {
  return models
    ? pickAlphaFoldModel(models, isoformSequences)
    : { accession: uniprotId, url: getAlphaFoldStructureUrl(uniprotId) }
}

/** Why a resolved gene has no structure to open. */
export function describeMissingStructure(
  geneName: string,
  { uniprotId, lookupError }: Pick<GeneLaunch, 'uniprotId' | 'lookupError'>,
) {
  return uniprotId
    ? `AlphaFold DB has no model for ${uniprotId}`
    : lookupError === undefined
      ? `No single UniProt entry found for ${geneName}`
      : `UniProt lookup failed for ${geneName}: ${errorText(lookupError)}`
}

function errorText(e: unknown) {
  return e instanceof Error ? e.message : `${e}`
}

/**
 * The entry a search names without a person choosing: the only hit, or the
 * only reviewed one. A gene-name search answers with the Swiss-Prot entry and
 * a tail of TrEMBL fragments, so the first row alone would also be right for
 * most human genes, and wrong in silence for the rest.
 */
export function unambiguousEntry(entries: UniProtEntry[]) {
  const reviewed = entries.filter(e => e.isReviewed)
  return entries.length === 1
    ? entries[0]
    : reviewed.length === 1
      ? reviewed[0]
      : undefined
}

/** What resolving a gene asks of the session and the network. */
export interface GeneLaunchHost {
  translate: (transcripts: Feature[]) => Promise<TranscriptTranslation[]>
  taxonId: () => Promise<number | undefined>
  rankIsoforms: (
    isoforms: Isoform[],
    structureSequences: string[],
  ) => Promise<IsoformRanking>
  searchUniProtEntries: typeof searchUniProtEntries
  fetchAlphaFoldModels: typeof fetchAlphaFoldModels
}

export function sessionGeneLaunchHost(
  session: AbstractSessionModel,
  assemblyName: string,
): GeneLaunchHost {
  return {
    translate: transcripts =>
      fetchTranscriptProteinSeqs({ transcripts, session, assemblyName }),
    taxonId: async () => {
      const assembly =
        await session.assemblyManager.waitForAssembly(assemblyName)
      return assembly
        ? extractTaxonId(getConf(assembly, ['sequence', 'metadata']))
        : undefined
    },
    rankIsoforms: (isoforms, structureSequences) =>
      alignOffThread({
        rpcManager: session.rpcManager,
        name: 'ProteinRankIsoforms',
        args: { isoforms, structureSequences },
        inPlace: () => rankIsoforms(isoforms, structureSequences),
      }),
    searchUniProtEntries,
    fetchAlphaFoldModels,
  }
}

/**
 * The accession a feature's identifiers name, or undefined where a person has
 * to choose. A gene symbol means a different protein in every species, so
 * without the assembly's taxon only the database ids are searched. An
 * unreachable UniProt resolves rather than throws, because the dialog takes a
 * typed accession and a spec can name one, and carries the error so a caller
 * does not report an outage as a gene with no entry.
 */
async function searchForEntry(
  host: GeneLaunchHost,
  ids: FeatureIdentifiers,
): Promise<EntryLookup> {
  try {
    const organismId = await host.taxonId()
    const geneName = organismId === undefined ? undefined : ids.geneName
    if (ids.recognizedIds.length === 0 && !geneName) {
      return {}
    }
    const { entries } = await host.searchUniProtEntries({
      recognizedIds: ids.recognizedIds,
      geneId: ids.geneId,
      geneName,
      organismId,
    })
    return { uniprotId: unambiguousEntry(entries)?.accession }
  } catch (e) {
    return { lookupError: e }
  }
}

/**
 * Everything the launch dialog works out from a gene, without the dialog: the
 * UniProt entry from the feature's identifiers, the AlphaFold model of that
 * entry, and the isoform to map — the preferred one when it translates, else
 * the one the model was folded from, else the annotation's MANE Select, else
 * the longest.
 */
export async function resolveGeneLaunch({
  host,
  feature,
  preferredTranscriptId,
  uniprotId: givenUniprotId,
  findStructure = true,
}: {
  host: GeneLaunchHost
  feature: Feature
  preferredTranscriptId?: string
  uniprotId?: string
  /** false when the caller names the structure, so UniProt is not asked */
  findStructure?: boolean
}): Promise<GeneLaunch> {
  const ids = extractFeatureIdentifiers(feature, preferredTranscriptId)
  const namedUniprotId =
    givenUniprotId ?? (findStructure ? ids.uniprotId : undefined)
  const lookup: EntryLookup | Promise<EntryLookup> =
    namedUniprotId !== undefined || !findStructure
      ? { uniprotId: namedUniprotId }
      : searchForEntry(host, ids)
  const [translations, { uniprotId, lookupError }] = await Promise.all([
    host.translate(codingTranscripts(feature)),
    lookup,
  ])
  const translated = translations.flatMap(({ feature: transcript, seq }) =>
    seq ? [{ transcript, seq }] : [],
  )
  if (translated.length === 0) {
    throw new Error('none of the transcripts could be translated')
  }
  const isoforms: Isoform[] = translated.map(t => ({
    id: t.transcript.id(),
    seq: t.seq,
  }))

  const model = uniprotId
    ? launchAlphaFoldModel(
        uniprotId,
        await host.fetchAlphaFoldModels(uniprotId).catch(() => undefined),
        Object.fromEntries(isoforms.map(i => [i.id, { seq: i.seq ?? '' }])),
      )
    : undefined
  const url = model?.url

  const structureSequences = model?.sequence ? [model.sequence] : []
  const preferred = translated.find(
    t => t.transcript.id() === preferredTranscriptId,
  )
  const ranking = preferred
    ? undefined
    : structureSequences.length > 0
      ? (await host.rankIsoforms(isoforms, structureSequences)).ranking
      : rankIsoforms(isoforms).ranking
  const bestId =
    ranking &&
    rankedTranscriptId(ranking, flaggedTranscriptId(codingTranscripts(feature)))
  const chosen =
    preferred ??
    translated.find(t => t.transcript.id() === bestId) ??
    translated[0]!

  return {
    transcript: chosen.transcript,
    userProvidedTranscriptSequence: chosen.seq,
    uniprotId,
    lookupError,
    url,
  }
}
